const legacyTypography={typography:{bodyFont:'Montserrat',headingFont:'Georgia',bodySize:18,h1:52,lineHeight:1.45,wrap:1250},other:{saved:true}};const typographyDefaults={typography:{bodyFont:'Manrope',headingFont:'Manrope',fontVersion:130,bodySize:15.5,h1:64,lineHeight:1.65,wrap:1200}};const migrated=ui.mergeDefaults(legacyTypography,typographyDefaults);assert.equal(migrated.typography.bodyFont,'Manrope');assert.equal(migrated.typography.headingFont,'Manrope');assert.equal(migrated.typography.fontVersion,130);assert.equal(migrated.typography.bodySize,18);assert.equal(migrated.typography.h1,52);assert.equal(migrated.typography.wrap,1250);assert.equal(migrated.other.saved,true);const chosen=ui.mergeDefaults({typography:{...migrated.typography,bodyFont:'Arial'}},typographyDefaults);assert.equal(chosen.typography.bodyFont,'Arial');assert.equal(ui.mergeDefaults(chosen,typographyDefaults).typography.bodyFont,'Arial');console.log('PASS: Manrope migration preserves type sizes, spacing, unrelated settings and later explicit font choices.');

// Build 152 tickets: the stub follows the real order.status, the full order.code is printed twice,
// both kinds keep their own fields, missing values are honest, everything is escaped, the existing
// actions and wrappers survive, and a status change patches only that ticket.
{
 const ticket=order=>ui.compactOrderHTML(order),occurrences=(text,part)=>text.split(part).length-1;
 const base={kind:'bookings',code:'AT-1D986905DA332E53F15A',tour:'available',date:'2027-01-15',time:'09:00',city:'Сухум',adults:2,kids:1,total:3800};
 for(const [status,visual,stamp] of [['completed','completed',''],['cancelled','cancelled','ОТМЕНЕНО'],['rejected','rejected','ОТКЛОНЕНО'],['awaiting_payment','active',''],['pending','active',''],['private','active',''],['needs_info','active',''],['confirmed','active',''],['paid','active',''],['brand_new_status','active','']]){
  const html=ticket({...base,status});
  assert.ok(html.includes(`data-ticket-visual="${visual}"`),status+' → '+visual);
  assert.ok(html.includes(`data-ticket-status="${status}"`),status+' is kept as the real status');
  if(stamp)assert.ok(html.includes('class="apsua-ticket-stamp"')&&html.includes(stamp),status+' stamp');else assert.ok(!html.includes('class="apsua-ticket-stamp"'),status+' has no stamp');
  assert.ok(html.includes('data-customer-order="bookings:AT-1D986905DA332E53F15A"')&&/data-order-fingerprint="[^"]+"/.test(html),'patch keys stay');
  assert.ok(!html.includes('Все данные заявки')&&!html.includes('order-all-data'),'no expandable row in the ticket');
 }
 assert.ok(ticket({...base,status:'brand_new_status'}).includes('Статус уточняется'),'an unknown status is not relabelled as a known one');
 assert.ok(ticket({...base,status:'confirmed',date:'2020-01-01'}).includes('data-ticket-visual="active"'),'a past date alone never tears the stub');
 const stateText=html=>(html.match(/class="apsua-ticket-state">([^<]+)</)||[])[1];assert.ok(stateText(ticket({...base,status:'pending'})));assert.equal(stateText(ticket({...base,status:'private'})),stateText(ticket({...base,status:'pending'})),'private reads like pending');assert.equal(stateText(ticket({...base,status:'needs_info'})),'Нужно уточнение');assert.equal(stateText(ticket({...base,status:'completed'})),'Завершена');
 const full=ticket({...base,status:'confirmed'});
 assert.equal(occurrences(full,'№ AT-1D986905DA332E53F15A'),2,'full real number on the ticket and on the stub');
 assert.ok(full.includes('Апсуа Тур')&&full.includes('>15<')&&full.includes('ЯНВ'),'stub shows the brand and the trip date');
 assert.match(full,/2 взр\. · 1 дет\./);assert.match(full,/3\s800 ₽/);assert.ok(full.includes('Сухум'));
 assert.ok(ticket({...base,code:undefined,status:'pending'}).includes('Номер уточняется'),'no invented number');
 const transfer=ticket({kind:'transfers',code:'TR-72B4C57CBE963A82F654',route:'Адлер → Гагра',status:'completed',date:'2027-01-13',time:'12:00',pax:2,price:5500});
 for(const token of ['data-ticket-kind="transfers"','Адлер → Гагра','2 пасс.','Время рейса / поезда','Маршрут','Трансфер','data-ticket-visual="completed"'])assert.ok(transfer.includes(token),'transfer ticket: '+token);
 assert.match(transfer,/5\s500 ₽/);assert.equal(occurrences(transfer,'№ TR-72B4C57CBE963A82F654'),2);
 for(const order of [{...base,status:'pending',total:null},{kind:'transfers',code:'TR-NOPRICE',route:'Сухум → Гагра',status:'pending'},{...base,status:'pending',total:'  '}]){const html=ticket(order);assert.ok(html.includes('По запросу'),'missing price is «По запросу»');assert.ok(!/>\s*0\s₽/.test(html),'never 0 ₽ for a missing price')}
 const unknown=ticket({kind:'bookings',code:'AT-EMPTY',status:'pending'});for(const token of ['Дата уточняется','Уточняется','Экскурсия'])assert.ok(unknown.includes(token),'honest placeholder: '+token);assert.ok(!unknown.includes('0 взр.'),'no invented guests');
 const hostile=ticket({...base,status:'pending',code:'<img src=x onerror=alert(1)>',city:'<b>город</b>',time:'<i>9</i>',meetingPoint:'<svg onload=1>',managerNote:'<script>x</script>'});
 for(const token of ['<img src=x','<b>город','<i>9','<svg onload','<script>'])assert.ok(!hostile.includes(token),'escaped: '+token);
 assert.ok(ticket({...base,status:'awaiting_payment'}).includes('>QR и оплата<'));assert.ok(ticket({...base,status:'confirmed'}).includes('>Открыть заявку<'));
 for(const status of ['cancelled','rejected']){const html=ticket({...base,status});assert.ok(!html.includes('data-trip-calendar')&&!html.includes('data-open-review'),status+' offers neither calendar nor review');assert.ok(html.includes('data-view-request="AT-1D986905DA332E53F15A"')&&html.includes('data-request-kind="bookings"'))}
 for(const status of ['confirmed','paid','completed'])assert.ok(ticket({...base,status}).includes('data-trip-calendar="AT-1D986905DA332E53F15A"'),status+' keeps «В календарь»');
 assert.ok(ticket({...base,status:'completed'}).includes('data-open-review'),'completed trip can be reviewed');
 const realTour=ui.getTours().find(t=>t.id&&!t.hidden);assert.ok(realTour,'a real tour exists');const linked=ticket({...base,tour:realTour.id,status:'confirmed'});assert.ok(linked.includes('href="#/excursions/'+encodeURIComponent(realTour.id)+'"'),'link to the excursion');assert.ok(linked.includes(realTour.title.replace(/&/g,'&amp;').replace(/</g,'&lt;')),'tour title from tourById');assert.ok(!ticket({...base,tour:'no-such-tour',status:'confirmed'}).includes('#/excursions/no-such-tour'),'no link for an unknown tour');
 const clarify=ticket({...base,status:'needs_info',clarification:{id:'q1',field:'manual',prompt:'Уточните отель'}});assert.ok(clarify.indexOf('data-clarification-reply')>0&&clarify.indexOf('data-clarification-reply')<clarify.indexOf('order-card-actions'),'clarification form stays under the ticket, above the buttons');
 const fleet=ticket({...base,status:'confirmed',assignedVehicle:{title:'Минивэн',registration:'А 123 АА'}});assert.ok(fleet.includes('fleet-assigned-summary')&&fleet.includes('А 123 АА'),'assigned vehicle is still shown');
 // Live update: only the changed ticket is replaced, and it is rebuilt from the new server status.
 let html='',replaced=0;const root={children:[],querySelectorAll(){return this.children},insertBefore(node,before){this.children=this.children.filter(x=>x!==node);this.children.splice(before?this.children.indexOf(before):this.children.length,0,node)},set innerHTML(v){throw new Error('Whole list must not be replaced')}};
 const node=order=>({dataset:{customerOrder:order.kind+':'+order.code,orderFingerprint:ui.orderCardFingerprint(order)},querySelector(){return null},remove(){root.children=root.children.filter(x=>x!==this)},set outerHTML(value){replaced++;html=value;const next=node(order);next.dataset.orderFingerprint=value.match(/data-order-fingerprint="([^"]+)"/)[1];next.html=value;root.children[root.children.indexOf(this)]=next}});
 const kept={...base,code:'AT-KEPT',status:'confirmed'},changing={...base,code:'AT-LIVE',status:'confirmed'};root.children=[node(kept),node(changing)];const keptNode=root.children[0];
 ui.patchOrderCards(root,[kept,{...changing,status:'completed'}]);assert.equal(replaced,1);assert.equal(root.children[0],keptNode,'untouched ticket keeps its DOM');assert.ok(html.includes('data-ticket-visual="completed"')&&html.includes('data-customer-order="bookings:AT-LIVE"'),'operator status change tears the stub on the next sync');
 ui.patchOrderCards(root,[kept,{...changing,status:'cancelled'}]);assert.equal(replaced,2);assert.ok(html.includes('ОТМЕНЕНО'));
 // Phones keep the ticket horizontal: the stub column stays on the right at every width.
 const css=readFileSync(new URL('../public/v152.css',import.meta.url),'utf8');
 assert.match(css,/\.apsua-ticket-paper\{display:grid;grid-template-columns:minmax\(0,1fr\) clamp\(124px,24%,220px\)/);
 assert.match(css,/@media \(max-width:600px\)\{[^@]*\.apsua-ticket-paper\{grid-template-columns:minmax\(0,1fr\) clamp\(100px,31%,132px\)/);
 assert.match(css,/@media \(max-width:360px\)\{[^@]*\.apsua-ticket-paper\{grid-template-columns:minmax\(0,1fr\) 96px\}/);
 assert.ok(!/\.apsua-ticket-paper\{[^}]*(grid-template-columns:minmax\(0,1fr\)\}|flex-direction:column|grid-template-rows)/.test(css),'the stub never drops under the ticket');
 assert.match(css,/\[data-ticket-visual="completed"\] \.apsua-ticket-stub\{transform:/);
 console.log('PASS: tickets — stub by real status (torn/cancelled/rejected/intact, unknown, past date), full real number twice, both kinds, honest placeholders, escaping, status-dependent actions, clarification and vehicle kept, single-ticket live patch, horizontal on phones.');
}

// Quick jump: an action tied to a jump runs only if that jump happens. «Отмена» at «Сохранить изменения?»
// leaves nothing behind, a newer jump replaces an older pending one, and the guard itself is unchanged.
{
 const frames=[],previousFrame=ctx.requestAnimationFrame;ctx.requestAnimationFrame=fn=>{frames.push(fn);return frames.length};const runFrames=()=>{for(let i=0;i<20&&frames.length;i++)frames.splice(0).forEach(fn=>fn())};
 const settle=()=>new Promise(resolve=>setImmediate(resolve));const mainNode=makeNode();nodes.set('#admMain',mainNode);
 const makeDirty=()=>{ui.getTours()[0].title='Черновик '+Math.random();ui.stageAdminContent();assert.equal(ctx.apsuaAdminDirty,true)};
 const answer=async choice=>{const dialog=nodes.get('dialog');assert.ok(dialog.innerHTML.includes('Сохранить изменения?'),'the unsaved-changes prompt is shown');if(choice===null)dialog.events.cancel({preventDefault(){}});else dialog.events.click({target:{closest:()=>({dataset:{exitChoice:choice}})}});await settle()};
 let fired=0;ctx.location.hash='#/admin/hero';mainNode.dataset.adminHash='#/admin/hero';
 makeDirty();ui.adminWhenOn('#/admin/tours',()=>fired++);await answer(null);
 assert.equal(ctx.location.hash,'#/admin/hero','cancel keeps the page');assert.equal(ctx.apsuaAdminDirty,true,'cancel keeps the edits');assert.equal(frames.length,0,'nothing is left waiting after cancel');
 ui.discardAdminChanges();ctx.location.hash='#/admin/tours';mainNode.dataset.adminHash='#/admin/tours';runFrames();assert.equal(fired,0,'a cancelled action never fires when the user later opens that page');
 ctx.location.hash='#/admin/hero';mainNode.dataset.adminHash='#/admin/hero';const before=JSON.stringify(ui.getRequestQueueState());
 makeDirty();ui.adminOpenOrder({code:'TR-CANCELLED',kind:'transfers'});await answer(null);assert.equal(JSON.stringify(ui.getRequestQueueState()),before,'a cancelled request jump does not touch the «Заявки» filter');
 makeDirty();ui.adminWhenOn('#/admin/tours',()=>fired++);mainNode.dataset.adminHash='#/admin/tours';await answer('no');runFrames();
 assert.equal(ctx.location.hash,'#/admin/tours','«Нет, выйти» still leaves');assert.equal(ctx.apsuaAdminDirty,false,'and discards the draft');assert.equal(fired,1,'the confirmed action runs exactly once');runFrames();assert.equal(fired,1);
 ctx.location.hash='#/admin/hero';mainNode.dataset.adminHash='#/admin/hero';makeDirty();ui.adminOpenOrder({code:'TR-CONFIRMED',kind:'transfers'});await answer('no');assert.equal(ui.getRequestQueueState().query,'TR-CONFIRMED','a confirmed request jump applies the filter');
 ctx.location.hash='#/admin/dash';mainNode.dataset.adminHash='#/admin/dash';ui.adminWhenOn('#/admin/push',()=>fired++);ui.adminGo('#/admin/reviews');mainNode.dataset.adminHash='#/admin/push';ctx.location.hash='#/admin/push';runFrames();assert.equal(fired,1,'a newer jump cancels the pending action of an older one');
 ctx.location.hash='#/admin/dash';mainNode.dataset.adminHash='#/admin/dash';ui.adminWhenOn('#/admin/backup',()=>fired++);ctx.location.hash='#/admin/settings';runFrames();ctx.location.hash='#/admin/backup';mainNode.dataset.adminHash='#/admin/backup';runFrames();assert.equal(fired,1,'leaving the target address on the way drops the action for good');
 ctx.location.hash='#/admin/tours';mainNode.dataset.adminHash='#/admin/tours';ui.adminWhenOn('#/admin/tours',()=>fired++);assert.equal(fired,2,'on the target page the action runs at once');
 ctx.requestAnimationFrame=previousFrame;nodes.delete('#admMain');
 console.log('PASS: quick-jump actions run only after a confirmed jump; «Отмена» leaves no pending action or filter, newer jumps and address changes drop older ones, the unsaved-changes prompt is unchanged.');
}
